package main

// ❌ OLD: Running with defaults (GOGC=100). The GC triggers when the
// heap roughly doubles since the last collection. For a service with
// bursty allocation, that means occasional large collections that
// consume CPU (GC assists + mark workers) right when the service is
// busiest — visible as latency spikes at the 99th percentile.
func main() {
	serveRequests() // ❌ OLD: no tuning, GC decides when to run
}

// No GOMEMLIMIT either — the heap can grow to the machine limit
// before pressure triggers a collection on spiky workloads.

package main

import "runtime/debug"

// ✅ NEW: Set a soft memory limit so GC runs as the heap approaches it
// (rather than only on percentage growth), and raise GOGC to reduce
// GC frequency when the limit bounds memory.
func main() {
	// ✅ NEW: soft limit — GC paces to stay under ~512MiB
	debug.SetMemoryLimit(512 << 20)
	// ✅ NEW: allow more growth between cycles (fewer, larger GCs)
	debug.SetGCPercent(200)

	serveRequests()
}

// The memory limit makes GC behavior predictable on bursty workloads;
// GOGC=200 reduces per-request GC CPU. Monitor runtime/metrics (e.g.
// /gc/heap/goal) to verify pacing.
